ALTER TABLE `communication_rules` DROP COLUMN `sign_off`;--> statement-breakpoint
-- Added by hand: the drafts, worded without `[firma]` and in the organization's `Trato` as its
-- rules have it now (docs/operations/whatsapp-templates.md). A draft is matched by the text
-- 0026 gave it, whatever its template is named since; a text an organization wrote stays.
UPDATE `template` SET `draft` = CASE (SELECT `form_of_address` FROM `communication_rules` WHERE `id` = 1) WHEN 'usted' THEN 'Hola {{paciente}}, le escribimos de {{organizacion}}: su turno con {{profesional}} quedó reservado para el {{fecha}} a las {{hora}} en {{sede}} ({{direccion}}). Si necesita cambiarlo, responda este mensaje.' ELSE 'Hola {{paciente}}, te escribimos de {{organizacion}}: tu turno con {{profesional}} quedó reservado para el {{fecha}} a las {{hora}} en {{sede}} ({{direccion}}). Si necesitás cambiarlo, respondé este mensaje.' END WHERE `draft` = 'Hola {{paciente}}, tu turno con {{profesional}} quedó reservado para el {{fecha}} a las {{hora}} en {{sede}} ({{direccion}}). Si necesitás cambiarlo, respondé este mensaje. [firma]';--> statement-breakpoint
